"""matplotlib.projections — projection registry.

Maps a projection name (``'rectilinear'``, ``'polar'``, ``'3d'``,
``'aitoff'``, ``'hammer'``, ``'lambert'``, ``'mollweide'``) to the
:class:`Axes` subclass that implements it. ``get_projection_class``
delegates to the registry; ``register_projection`` is how 3rd-party
backends plug in custom projections.
"""

from matplotlib.projections.polar import PolarAxes
from matplotlib.projections.geo import (
    AitoffAxes, HammerAxes, MollweideAxes, LambertAxes)


def _rectilinear_class():
    """Late-bound to avoid a circular import at module load (axes →
    projections → axes)."""
    from matplotlib.axes import Axes
    return Axes


def _axes3d_class():
    """Late-bound to avoid pulling mpl_toolkits at module load."""
    try:
        from mpl_toolkits.mplot3d import Axes3D
        return Axes3D
    except Exception:
        return _rectilinear_class()


_projections = {
    'rectilinear': _rectilinear_class,
    'polar':       PolarAxes,
    'aitoff':      AitoffAxes,
    'hammer':      HammerAxes,
    'mollweide':   MollweideAxes,
    'lambert':     LambertAxes,
    '3d':          _axes3d_class,
}


def _resolve(entry):
    """Allow a lazy callable (``_rectilinear_class``) or a class."""
    if callable(entry) and not isinstance(entry, type):
        return entry()
    return entry


def get_projection_names():
    """Return the sorted list of every registered projection name."""
    return sorted(_projections.keys())


def get_projection_class(projection=None):
    """Look up the :class:`Axes` subclass for ``projection``.

    Falls back to the rectilinear axes when the name is unknown so
    callers don't crash on typos — mirrors upstream's behaviour."""
    if projection is None:
        return _rectilinear_class()
    entry = _projections.get(projection)
    if entry is None:
        return _rectilinear_class()
    return _resolve(entry)


def register_projection(cls):
    """Register a new projection class. ``cls.name`` is used as the
    lookup key — mirrors upstream's contract."""
    if not hasattr(cls, 'name'):
        raise ValueError("projection class must define a 'name' attribute")
    _projections[cls.name] = cls
    # Keep the singleton registry in sync.
    projection_registry._all_projection_types[cls.name] = cls


def projection_factory(projection, figure, rect, **kwargs):
    """Build an axes for ``projection`` inside ``figure`` at ``rect``."""
    cls = get_projection_class(projection)
    if cls is None:
        return None
    try:
        return cls(figure, rect, **kwargs)
    except TypeError:
        # Some axes subclasses (Axes3D) don't accept rect — try without.
        try: return cls(figure, **kwargs)
        except TypeError: return cls(figure)


# ─── Added: missing public names from upstream projections ─────────


class ProjectionRegistry:
    """Mapping from a projection name to its Axes class. Mirrors
    upstream's class of the same name — wraps the module-level
    ``_projections`` dict with register/get methods."""

    def __init__(self):
        self._all_projection_types = dict(_projections)

    def register(self, *projections):
        for proj in projections:
            self._all_projection_types[proj.name] = proj

    def get_projection_class(self, name):
        return self._all_projection_types.get(name)

    def get_projection_names(self):
        return sorted(self._all_projection_types.keys())


# Singleton — matches upstream's module-level instance.
projection_registry = ProjectionRegistry()
